{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening parts and tools in storage, assemble the target on the workbench, and return tools.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "FIXED_TARGET",
        "function": "Primary surface where the fastening task occurs and where tools must be left.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["workbench", "table"],
        "required_properties": ["horizontal surface", "drawers", "storage space"]
      },
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The specific assembly or component requiring fastening at the marked location.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "bracket", "hinge", "part"],
        "required_properties": ["needs fastening", "located on workbench"]
      },
      {
        "id": "storage_unit",
        "entity_kind": "REGION",
        "function": "Enclosed spaces containing necessary components and equipment.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "cupboard"],
        "required_properties": ["enclosed", "accessible", "contains items"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "The specific part needed to secure the fastening target.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "clip", "washer", "fastener"],
        "required_properties": ["compatible with target", "fits fastening mechanism"]
      },
      {
        "id": "fastening_equipment",
        "entity_kind": "OBJECT",
        "function": "Tools required to perform the fastening action.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "pincer", "tool"],
        "required_properties": ["usable for fastening", "portable"]
      }
    ],
    "functional_relations": [
      {
        "id": "target_location",
        "relation": "is located on",
        "participant_roles": ["fastening_target", "workbench"]
      ,
        "required": true
      },
      {
        "id": "component_source",
        "relation": "is stored inside",
        "participant_roles": ["fastening_component", "storage_unit"]
      ,
        "required": true
      },
      {
        "id": "equipment_source",
        "relation": "is stored inside",
        "participant_roles": ["fastening_equipment", "storage_unit"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "open_storage",
        "operation": "open",
        "participant_roles": ["storage_unit", "robot_arm"],
        "operation_count": 3
      },
      {
        "id": "retrieve_parts",
        "operation": "retrieve",
        "participant_roles": ["fastening_component", "storage_unit"],
        "operation_count": 1
      },
      {
        "id": "retrieve_tools",
        "operation": "retrieve",
        "participant_roles": ["fastening_equipment", "storage_unit"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "fasten",
        "participant_roles": ["fastening_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "return_equipment",
        "operation": "place",
        "participant_roles": ["fastening_equipment", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        { "label": "wooden_table", "visual_description": "Wooden table with drawers and a cabinet on top." }
      ],
      "fastening_target": [
        { "label": "yellow_blue_object", "visual_description": "Yellow and blue mechanical part sitting on a black tray." }
      ],
      "storage_unit": [
        { "label": "left_drawer", "visual_description": "Blue drawer on the left side under the table." },
        { "label": "right_drawer", "visual_description": "Blue drawer on the right side under the table." },
        { "label": "cabinet", "visual_description": "Tall dark grey cabinet standing behind the table." }
      ],
      "fastening_component": [],
      "fastening_equipment": []
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left Drawer",
        "visual_description": "Closed blue drawer with handle.",
        "reason": "Standard storage location for small components or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right Drawer",
        "visual_description": "Closed blue drawer with handle.",
        "reason": "Standard storage location for small components or tools."
      },
      {
        "id": "cabinet",
        "label": "Cabinet",
        "visual_description": "Closed dark grey cabinet with handle.",
        "reason": "Likely contains larger tools or spare parts."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
